<?php
declare(strict_types=1);
namespace CommunityHub;
final class FlowAdmin {
 const TRIGGERS=['application_submitted','application_status_changed','training_registered','training_completed','lms_completed','member_status_changed','manual'];
 const ACTIONS=['create_notification','set_member_status','set_recruit_stage','write_staff_note','write_audit_log'];
 const OPERATORS=['equals','not_equals','contains','not_contains','in','not_in','is_empty','is_not_empty'];
 public static function handle(array $u,string $method,string $path,array $d):void{Domain::role($u,Domain::ADMINS);if($method==='POST'){if($path==='/admin/automations/create'){if(!in_array($d['trigger_type']??'',self::TRIGGERS,true))throw new HttpError('Select a valid trigger.');App::query('INSERT INTO automation_flows(name,description,trigger_type,is_enabled,created_by,updated_by) VALUES(?,?,?,?,?,?)',[App::text($d['name']??null,'Flow name',180),$d['description']?:null,$d['trigger_type'],(int)!empty($d['is_enabled']),$u['id'],$u['id']]);App::redirect('/admin/automations');}if(!preg_match('~^/admin/automations/(\d+)/(toggle|condition|action|run)$~',$path,$m))throw new HttpError('Flow action not found.',404);$id=(int)$m[1];if(!App::row('SELECT id FROM automation_flows WHERE id=?',[$id]))throw new HttpError('Flow not found.',404);switch($m[2]){case 'toggle':App::query('UPDATE automation_flows SET is_enabled=IF(is_enabled=1,0,1),updated_by=? WHERE id=?',[$u['id'],$id]);break;case 'condition':if(!in_array($d['operator_name']??'',self::OPERATORS,true))throw new HttpError('Select a valid condition operator.');App::query('INSERT INTO automation_conditions(flow_id,sort_order,field_name,operator_name,comparison_value) VALUES(?,?,?,?,?)',[$id,(int)($d['sort_order']??0),App::text($d['field_name']??null,'Field name',120),$d['operator_name'],$d['comparison_value']?:null]);break;case 'action':if(!in_array($d['action_type']??'',self::ACTIONS,true))throw new HttpError('Select a valid action.');try{$json=json_decode($d['action_config_json']?:'{}',true,64,JSON_THROW_ON_ERROR);if(!is_array($json))throw new \JsonException();}catch(\JsonException $e){throw new HttpError('Action configuration must be a JSON object.');}App::query('INSERT INTO automation_actions(flow_id,sort_order,action_type,action_config_json) VALUES(?,?,?,?)',[$id,(int)($d['sort_order']??0),$d['action_type'],json_encode($json,JSON_THROW_ON_ERROR)]);break;case 'run':if(!App::row("SELECT id FROM automation_flows WHERE id=? AND trigger_type='manual' AND is_enabled=1",[$id]))throw new HttpError('Enabled manual flow not found.',404);Automation::emit('manual',['entity_type'=>'automation_flow','entity_id'=>$id,'subject_user_id'=>!empty($d['subject_user_id'])?App::id($d['subject_user_id']):null,'manual_flow_id'=>$id],(int)$u['id'],$id);break;}App::redirect('/admin/automations');}if($path!=='/admin/automations')throw new HttpError('Page not found.',404);View::layout('CommunityHub Flow',function(){View::heading('CommunityHub Flow','Automate community actions when applications and training change.');foreach(App::rows('SELECT * FROM automation_flows ORDER BY updated_at DESC') as $f){?><section class="panel"><h2><?=escape($f['name'])?></h2><p><?=escape($f['trigger_type'])?> · <?=$f['is_enabled']?'Enabled':'Disabled'?></p><?php View::form('/admin/automations/'.$f['id'].'/toggle',[],'Toggle flow');View::table(App::rows('SELECT field_name,operator_name,comparison_value FROM automation_conditions WHERE flow_id=? ORDER BY sort_order,id',[$f['id']]),['field_name'=>'Field','operator_name'=>'Operator','comparison_value'=>'Value']);View::form('/admin/automations/'.$f['id'].'/condition',['field_name'=>['label'=>'Context field','required'=>true],'operator_name'=>['label'=>'Operator','options'=>array_combine(self::OPERATORS,self::OPERATORS)],'comparison_value'=>'Comparison value','sort_order'=>['label'=>'Order','type'=>'number']],'Add condition');View::table(App::rows('SELECT action_type,action_config_json FROM automation_actions WHERE flow_id=? ORDER BY sort_order,id',[$f['id']]),['action_type'=>'Action','action_config_json'=>'Configuration']);View::form('/admin/automations/'.$f['id'].'/action',['action_type'=>['label'=>'Action','options'=>array_combine(self::ACTIONS,self::ACTIONS)],'action_config_json'=>['label'=>'Configuration JSON','type'=>'textarea','default'=>'{}'],'sort_order'=>['label'=>'Order','type'=>'number']],'Add action');if($f['trigger_type']==='manual')View::form('/admin/automations/'.$f['id'].'/run',['subject_user_id'=>['label'=>'Subject user ID','type'=>'number']],'Run flow');?></section><?php }View::form('/admin/automations/create',['name'=>['label'=>'Flow name','required'=>true],'description'=>['label'=>'Description','type'=>'textarea'],'trigger_type'=>['label'=>'Trigger','options'=>array_combine(self::TRIGGERS,self::TRIGGERS)],'is_enabled'=>['label'=>'Enabled','type'=>'checkbox','default'=>true]],'Create flow');?><section class="panel"><h2>Recent runs</h2><?php View::table(App::rows('SELECT r.*,f.name flow_name FROM automation_runs r JOIN automation_flows f ON f.id=r.flow_id ORDER BY r.id DESC LIMIT 50'),['flow_name'=>'Flow','trigger_type'=>'Trigger','status'=>'Status','error_message'=>'Error','started_at'=>'Started']);?></section><?php });}
}
